-- PoolLog 0.1 – in Supabase SQL Editor ausführen.
-- Benutzer und Hotelzuordnungen werden bewusst nur administrativ angelegt.
create extension if not exists pgcrypto;
create table if not exists public.hotels (id uuid primary key default gen_random_uuid(), name text not null);
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,hotel_id uuid not null references public.hotels(id),role text not null check(role in ('staff','manager','admin','viewer')));
create table if not exists public.day_logs (id uuid primary key default gen_random_uuid(),hotel_id uuid not null references public.hotels(id),day date not null,responsible_user_id uuid not null references public.profiles(id),status text not null default 'draft' check(status in ('draft','submitted','returned','approved')),data jsonb not null default '{}'::jsonb,review_note text,reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(hotel_id,day));
create table if not exists public.readings (id uuid primary key default gen_random_uuid(),day_log_id uuid not null references public.day_logs(id) on delete cascade,round text not null check(round in ('Morgen','Abend')),point_id text not null check(point_id in ('innen','aussen','plansch','rutsche','warm','whirlpool','kalt_innen','kalt_aussen')),values jsonb not null default '{}'::jsonb,note text not null default '',recorded_by uuid not null default auth.uid() references public.profiles(id),recorded_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(day_log_id,round,point_id));
create table if not exists public.audit_events (id bigint generated always as identity primary key,hotel_id uuid not null references public.hotels(id),actor_id uuid references public.profiles(id),table_name text not null,record_id uuid not null,operation text not null,old_data jsonb,new_data jsonb,at timestamptz not null default now());
create or replace function public.my_hotel() returns uuid language sql stable security definer set search_path=public as $$select hotel_id from public.profiles where id=auth.uid()$$;
create or replace function public.my_role() returns text language sql stable security definer set search_path=public as $$select role from public.profiles where id=auth.uid()$$;
create or replace function public.can_edit_log(p_id uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.day_logs d where d.id=p_id and d.hotel_id=public.my_hotel() and d.responsible_user_id=auth.uid() and d.status in ('draft','returned'))$$;
create or replace function public.audit_changes() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.audit_events(hotel_id,actor_id,table_name,record_id,operation,old_data,new_data) values(coalesce(new.hotel_id,old.hotel_id),auth.uid(),tg_table_name,coalesce(new.id,old.id),tg_op,case when tg_op='INSERT' then null else to_jsonb(old) end,case when tg_op='DELETE' then null else to_jsonb(new) end);return coalesce(new,old);end$$;
-- readings besitzen keine hotel_id; Hotel wird aus dem Tagesprotokoll abgeleitet.
create or replace function public.audit_reading() returns trigger language plpgsql security definer set search_path=public as $$declare h uuid;begin select hotel_id into h from public.day_logs where id=coalesce(new.day_log_id,old.day_log_id);insert into public.audit_events(hotel_id,actor_id,table_name,record_id,operation,old_data,new_data) values(h,auth.uid(),tg_table_name,coalesce(new.id,old.id),tg_op,case when tg_op='INSERT' then null else to_jsonb(old) end,case when tg_op='DELETE' then null else to_jsonb(new) end);return coalesce(new,old);end$$;
create or replace function public.guard_day_log() returns trigger language plpgsql set search_path=public as $$begin if tg_op='UPDATE' then if current_user <> 'postgres' and (new.hotel_id is distinct from old.hotel_id or new.day is distinct from old.day or new.responsible_user_id is distinct from old.responsible_user_id or new.status is distinct from old.status or new.review_note is distinct from old.review_note or new.reviewed_by is distinct from old.reviewed_by or new.reviewed_at is distinct from old.reviewed_at) then raise exception 'Status und Zuordnung dürfen nur über den Freigabeprozess geändert werden';end if;if current_user <> 'postgres' and old.status not in ('draft','returned') then raise exception 'Protokoll ist gesperrt';end if;end if;new.updated_at=now();return new;end$$;
create or replace function public.guard_reading() returns trigger language plpgsql set search_path=public as $$begin if not public.can_edit_log(new.day_log_id) then raise exception 'Keine Bearbeitungsberechtigung';end if;if tg_op='UPDATE' and (new.day_log_id is distinct from old.day_log_id or new.round is distinct from old.round or new.point_id is distinct from old.point_id or new.recorded_by is distinct from old.recorded_by) then raise exception 'Messstellen-Zuordnung unveränderlich';end if;new.updated_at=now();return new;end$$;
drop trigger if exists guard_day on public.day_logs;create trigger guard_day before update on public.day_logs for each row execute function public.guard_day_log();
drop trigger if exists audit_day on public.day_logs;create trigger audit_day after insert or update or delete on public.day_logs for each row execute function public.audit_changes();
drop trigger if exists guard_measurement on public.readings;create trigger guard_measurement before insert or update on public.readings for each row execute function public.guard_reading();
drop trigger if exists audit_measurement on public.readings;create trigger audit_measurement after insert or update or delete on public.readings for each row execute function public.audit_reading();
alter table public.hotels enable row level security;alter table public.profiles enable row level security;alter table public.day_logs enable row level security;alter table public.readings enable row level security;alter table public.audit_events enable row level security;
create policy "hotel read" on public.hotels for select to authenticated using(id=public.my_hotel());
create policy "profile read" on public.profiles for select to authenticated using(hotel_id=public.my_hotel());
create policy "day read" on public.day_logs for select to authenticated using(hotel_id=public.my_hotel());
create policy "day insert" on public.day_logs for insert to authenticated with check(hotel_id=public.my_hotel() and responsible_user_id=auth.uid() and public.my_role() in ('staff','admin') and status='draft' and data='{}'::jsonb);
create policy "day edit" on public.day_logs for update to authenticated using(hotel_id=public.my_hotel() and responsible_user_id=auth.uid() and status in ('draft','returned')) with check(hotel_id=public.my_hotel() and responsible_user_id=auth.uid());
create policy "reading read" on public.readings for select to authenticated using(exists(select 1 from public.day_logs d where d.id=day_log_id and d.hotel_id=public.my_hotel()));
create policy "reading insert" on public.readings for insert to authenticated with check(public.can_edit_log(day_log_id) and recorded_by=auth.uid());
create policy "reading update" on public.readings for update to authenticated using(public.can_edit_log(day_log_id) and recorded_by=auth.uid()) with check(public.can_edit_log(day_log_id) and recorded_by=auth.uid());
create policy "audit read" on public.audit_events for select to authenticated using(hotel_id=public.my_hotel() and public.my_role() in ('manager','admin'));
-- Statuswechsel ausschließlich über RPC. Security definer, eigene Rollen-/Mandantenprüfung.
create or replace function public.transition_day_log(p_log_id uuid,p_action text,p_note text default '') returns void language plpgsql security definer set search_path=public as $$declare d public.day_logs%rowtype; n int;begin select * into d from public.day_logs where id=p_log_id for update;if not found or d.hotel_id is distinct from public.my_hotel() then raise exception 'Protokoll nicht gefunden';end if;if p_action='submit' then if d.responsible_user_id<>auth.uid() or d.status not in ('draft','returned') then raise exception 'Einreichen nicht erlaubt';end if;select count(*) into n from public.readings where day_log_id=p_log_id;if n<>16 then raise exception 'Morgen- und Abendrunde müssen vollständig sein (16 Einträge)';end if;update public.day_logs set status='submitted',review_note=null,reviewed_by=null,reviewed_at=null,updated_at=now() where id=p_log_id;elsif p_action in ('approve','return') then if public.my_role() not in ('manager','admin') or d.responsible_user_id=auth.uid() or d.status<>'submitted' then raise exception 'Freigabe nicht erlaubt';end if;if p_action='return' and trim(p_note)='' then raise exception 'Rückgabegrund fehlt';end if;update public.day_logs set status=case when p_action='approve' then 'approved' else 'returned' end,review_note=p_note,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=p_log_id;else raise exception 'Ungültige Aktion';end if;insert into public.audit_events(hotel_id,actor_id,table_name,record_id,operation,old_data,new_data) values(d.hotel_id,auth.uid(),'day_logs',d.id,'TRANSITION',to_jsonb(d),jsonb_build_object('action',p_action,'note',p_note));end$$;
revoke all on function public.transition_day_log(uuid,text,text) from public;grant execute on function public.transition_day_log(uuid,text,text) to authenticated;
-- Kein automatisches Benutzer-Onboarding: Hotel und Profile werden mit Service-Rolle angelegt.
